INSERT INTO tb_popup (  title
                      , start_dttm
                      , end_dttm
                      , loca_hi
                      , loca_wi
                      , size_hi
                      , size_wi
                      , use_yn
                      , del_yn
                      , contents
                      , creat_dttm
                      , crtr_id
                      , updt_dttm
                      , updusr_id
                      ) VALUES(
                        #{title}
                      , #{start_dttm}
                      , #{end_dttm}
                      , #{loca_hi}
                      , #{loca_wi}
                      , #{size_hi}
                      , #{size_wi}
                      , #{use_yn}
                      , "N"
                      , #{contents}
                      , now()
                      , #{crtr_id}
                      , now()
                      , #{crtr_id}
                      )
